  "cour.inst.c.tex": "\\begin{aligned} q^* &= \\frac{a-c}{3b} = \\frac{{va} - {vc}}{3 \\cdot {vb}} = {vq} \\\\ P^* &= a - b\\,(q_1^* + q_2^*) = {va} - {vb}\\,({vq} + {vq}) = {vP} \\\\ \\pi_i^* &= (P^* - c)\\,q_i^* = ({vP} - {vc}) \\cdot {vq} = {vpm}\\ \\text{millones de pesos} \\end{aligned}",
  "cour.inst.c.formula": "q* = (a − c)/(3b) = ({va} − {vc})/(3·{vb}) = {vq}\nP* = {va} − {vb}·({vq} + {vq}) = {vP}\nπ* = ({vP} − {vc})·{vq} = {vpm} millones de pesos",
  "cour.inst.s.tex": "\\begin{aligned} q_1 &= \\frac{a-c}{2b} = \\frac{{va} - {vc}}{2 \\cdot {vb}} = {vL} \\\\ q_2 &= R_2(q_1) = \\frac{{va} - {vc} - {vb} \\cdot {vL}}{2 \\cdot {vb}} = {vF} \\\\ P &= {va} - {vb}\\,({vL} + {vF}) = {vP} \\\\ \\pi_1 &= ({vP} - {vc}) \\cdot {vL} = {vp1}\\ \\text{millones de pesos} \\\\ \\pi_2 &= ({vP} - {vc}) \\cdot {vF} = {vp2}\\ \\text{millones de pesos} \\end{aligned}",
  "cour.inst.s.formula": "q₁ = (a − c)/(2b) = ({va} − {vc})/(2·{vb}) = {vL}\nq₂ = R₂(q₁) = ({va} − {vc} − {vb}·{vL})/(2·{vb}) = {vF}\nP = {va} − {vb}·({vL} + {vF}) = {vP}\nπ₁ = ({vP} − {vc})·{vL} = {vp1} millones de pesos\nπ₂ = ({vP} − {vc})·{vF} = {vp2} millones de pesos",

